package org.example.behavioral_pattern.strategy_pattern.delivery.impl;import org.example.behavioral_pattern.strategy_pattern.delivery.Order;import org.example.behavioral_pattern.strategy_pattern.delivery.ShippingStrategy;public class ExpressShippingStrategy implements ShippingStrategy {    @Override    public int calculateFee(Order order) {        int baseFee = 50;        if (order.getWeightInGram() > 1000) {            baseFee += 10;        }        return baseFee;    }}